import pandas as pd
import numpy as np
from scipy import stats

# Load all experiments
exps = {}
for name in ['1','2','3','7','8','11']:
    path = globals()[f'experiment_{name}_csv']
    exps[name] = pd.read_csv(path)

print("=== COLUMNS IN EACH EXPERIMENT ===")
for k,v in exps.items():
    print(f"Exp {k}: {list(v.columns)}")

print("\n=== LOOKING FOR INTERVENTION INDICATORS (columns with low variance) ===")
for k,v in exps.items():
    for col in v.columns:
        if col != 'unit_id':
            sd = v[col].std()
            mean = v[col].mean()
            if sd < 2 and mean > 10:  # likely fixed/intervention column
                print(f"  Exp {k}: {col} mean={mean:.1f} std={sd:.1f} - LIKELY INTERVENTION")

print("\n=== PRODUCT TITER MEANS ACROSS EXPERIMENTS ===")
for k,v in exps.items():
    if 'ProductTiter' in v.columns:
        print(f"  Exp {k}: mean titer = {v['ProductTiter'].mean():.1f}")

print("\n=== CORRELATIONS WITH TITER (where available) ===")
for k,v in exps.items():
    if 'ProductTiter' in v.columns and len(v.columns) > 2:
        corr_with_titer = v.corr(numeric_only=True)['ProductTiter'].drop('ProductTiter')
        print(f"\nExp {k}:")
        for col, val in corr_with_titer.items():
            print(f"  {col}: {val:.3f}")

